// 生まれた年ごとの名 (src/data/name-eras.json) を書き出す。identity.json の名はいまの名なので、昔に生まれた人にはここから引く。
// [この年より前に生まれた人, 名]。どの帯にも入らない人は identity.json の名。漢字・ハングルの名は英語表記を同じ順に並べる
// 出典: 日本=明治安田生命「生まれ年別名前ランキング」(1912〜)。韓国=大法院 電子家族関係登録「出生年度別 人気の名」(1945〜) と
//   日本統治期の戸籍に多い「〜子」の名。中国=公安部「全国姓名報告」の年代別の名 (建国・秀英など)。
//   英語=米国 SSA "Popular Baby Names" (1900〜) と英 ONS "Baby names in England and Wales 1904–1994"。
//   ドイツ=Knud Bielefeld "beliebte-vornamen.de" の年別順位。フランス=INSEE「Fichier des prénoms」(1900〜)。
//   スペイン=INE「Nombres por fecha de nacimiento」(年代別)。ブラジル=IBGE 2010年国勢調査「Nomes no Brasil」(年代別)。
//   イタリア・ポーランド・ロシアなど=各国の統計局の年代別の名と Behind the Name の年代別の頻度。
//   南アジア・中東・アフリカは年代別の統計が乏しい。当時の名簿・人名録によく見える名を目安にした (ponytail: 目安)
// 使い方: node scripts/build-name-eras.mjs
import { writeFileSync } from 'node:fs';

const L = (s) => s.split(',').map((x) => x.trim()).filter(Boolean);
const band = (until, male, female, maleEn, femaleEn) => [until, {
  male: L(male), female: L(female), ...(maleEn ? { maleEn: L(maleEn), femaleEn: L(femaleEn) } : {}),
}];

