// 名と英語表記の数が合わない帯を見つけたら止める
for (const [id, bands] of Object.entries(E)) for (const [until, b] of bands) {
  for (const k of ['male', 'female']) {
    const list = b[k].filter((x) => !x.includes('?'));
    if (list.length !== b[k].length) throw new Error(`${id} ${until} ${k}: ? が残っている`);
    if (list.length < 25) throw new Error(`${id} ${until} ${k}: ${list.length}件しかない`);
    if (b[k + 'En'] && b[k + 'En'].length !== list.length) throw new Error(`${id} ${until} ${k}En: ${b[k + 'En'].length} != ${list.length}`);
  }
}
const out = new URL('../src/data/name-eras.json', import.meta.url);
writeFileSync(out, JSON.stringify(E, null, 1) + '\n');
console.log(Object.keys(E).length, 'pools');
